/* HEXA BATTLEGROUNDS setup — PART 57 OF 82. Run parts in order. Safe to re-run. */ create function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare v boolean; begin v := _tick_core(p_arena, p_force); if exists (select 1 from bots where arena_id = p_arena) then if _bots_step(p_arena) then v := true; end if; end if; return v; end $$; create or replace function arena_positions(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_scan boolean; begin p := _auth_player(p_token); select * into t from teams where id = p.team_id; if exists (select 1 from bots where arena_id = t.arena_id) then perform _tick(t.arena_id); end if; v_scan := t.scan_until is not null and t.scan_until > now(); return jsonb_build_object('server_now', now(), 'squads', (select coalesce(jsonb_agg(jsonb_build_object( 'id', tm.id, 'level', tm.level, 'bldg', tm.bldg, 'state', tm.state, 'pos', to_jsonb(_team_xy(tm)), 'age', case when tm.state = 'idle' and tm.pos_at is not null then round(extract(epoch from now() - tm.pos_at)::numeric, 2) end, 'vel', case when tm.state = 'traveling' and tm.travel_arrive_at > now() and l.id is not null then jsonb_build_array((l.x - coalesce(tm.travel_fx, l.x)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at)), (l.y - coalesce(tm.travel_fy, l.y)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at))) when tm.state = 'idle' and tm.pos_at > now() - interval '3 seconds' and (tm.vel_x <> 0 or tm.vel_y <> 0) then jsonb_build_array(tm.vel_x, tm.vel_y) end)), '[]'::jsonb) from teams tm left join locations l on l.id = tm.travel_to where tm.arena_id = t.arena_id and tm.ready and (tm.id = t.id or v_scan or tm.location_id = t.location_id or tm.jammed_until is null or tm.jammed_until < now() or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = tm.id) or (al.team_b = t.id and al.team_a = tm.id)))))); end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; alter table arenas add column if not exists zone_shrink_from timestamptz; alter table arenas add column if not exists zone_shrink_until timestamptz; alter table arenas add column if not exists plane_ax float8; alter table arenas add column if not exists plane_ay float8; alter table arenas add column if not exists plane_bx float8; alter table arenas add column if not exists plane_by float8; alter table arenas add column if not exists plane_t0 timestamptz; alter table arenas add column if not exists plane_t1 timestamptz; alter table teams add column if not exists vehicle text not null default 'none'; alter table teams add column if not exists buggy_x float8; alter table teams add column if not exists buggy_y float8; alter table teams add column if not exists kills int not null default 0; alter table teams add column if not exists fight_at timestamptz; alter table players add column if not exists shot_at timestamptz; alter table players add column if not exists mag int; alter table players add column if not exists reload_until timestamptz; do $$ begin alter table teams add constraint teams_vehicle_chk check (vehicle in ('none', 'in', 'parked')); exception when duplicate_object then null; end $$; do $$ begin if not exists (select 1 from app_secrets where key = 'v6_vehicles') then update teams set vehicle = 'in' where dropped and vehicle = 'none'; insert into app_secrets(key, value) values ('v6_vehicles', 'done'); end if; end $$; drop function if exists _defaults_v5(); alter function _defaults() rename to _defaults_v5; create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v5() || jsonb_build_object( 'zone_shrink', 40, 'zone_tick_seconds', 2, 'zone_tick_damage', 2, 'foot_speed', 6, 'fire_from_phase', 1, 'kill_points', 60, 'kill_coins', 25, 'glide_range', 300, 'plane_seconds', 55, 'drop_seconds', 12, 'shuttle_seconds', 40, 'roles_seconds', 6, 'br_mode', 1) $$; drop function if exists _auto_preset_v5(text); alter function _auto_preset(text) rename to _auto_preset_v5; create function _auto_preset(p_length text) returns jsonb language sql immutable as $$ select _auto_preset_v5(p_length) || jsonb_build_object('shuttle_seconds', 40, 'roles_seconds', 6, 'zone_shrink', case p_length when 'quick' then 25 when 'full' then 60 else 40 end) $$; create or replace function _zone_now(p_arena uuid) returns float8[] language plpgsql stable as $$ declare a arenas; c float8[]; o float8[]; p float8; begin select * into a from arenas where id = p_arena; c := _zone_circle(a.event_id, a.zone_stage); if a.zone_stage > 0 and a.zone_shrink_until is not null and now() < a.zone_shrink_until then o := _zone_circle(a.event_id, a.zone_stage - 1); p := least(1, greatest(0, extract(epoch from now() - a.zone_shrink_from) / greatest(1, extract(epoch from a.zone_shrink_until - a.zone_shrink_from)))); return array[o[1] + (c[1] - o[1]) * p, o[2] + (c[2] - o[2]) * p, o[3] + (c[3] - o[3]) * p]; end if; return c; end $$; create or replace function _zone_dmg(p_event uuid, p_stage int) returns int language sql stable as $$ select _cfg(p_event, 'zone_tick_damage') * (array[1, 1, 2, 3, 5, 8])[least(5, greatest(0, coalesce(p_stage, 0))) + 1] $$; create or replace function _zone_advance(p_arena uuid) returns void language plpgsql as $$ declare a arenas; begin update arenas set zone_stage = least(5, zone_stage + 1), zone_next_at = null, zone_shrink_from = now(), zone_shrink_until = now() + _secs(_cfg(event_id, 'zone_shrink')) where id = p_arena returning * into a; perform _feed(p_arena, 'zone.collapsed', jsonb_build_object('stage', a.zone_stage)); perform _apply_zone(p_arena); end $$; create or replace function _apply_zone(p_arena uuid) returns void language plpgsql as $$ declare r record; begin for r in select id from teams where arena_id = p_arena and ready loop perform _ping_team(r.id, 'zone'); end loop; perform _zone_publish(p_arena); end $$; create or replace function _zone_publish(p_arena uuid) returns void language plpgsql as $$ declare a arenas; cur float8[]; nxt float8[]; prv float8[]; begin select * into a from arenas where id = p_arena; if a.id is null then return; end if; cur := _zone_circle(a.event_id, a.zone_stage); if a.zone_next_at is not null and a.zone_stage < 5 then nxt := _zone_circle(a.event_id, a.zone_stage + 1); end if; if a.zone_stage > 0 and a.zone_shrink_until is not null and a.zone_shrink_until > now() then prv := _zone_circle(a.event_id, a.zone_stage - 1); end if; update arenas set overlay = (overlay - 'zone' - 'red') || jsonb_build_object( 'zone', jsonb_build_object('stage', a.zone_stage, 'cur', to_jsonb(cur), 'next', to_jsonb(nxt), 'next_at', a.zone_next_at, 'prev', to_jsonb(prv), 'shrink_from', case when prv is not null then a.zone_shrink_from end, 'shrink_until', case when prv is not null then a.zone_shrink_until end, 'dps', round(_zone_dmg(a.event_id, a.zone_stage)::numeric / greatest(1, _cfg(a.event_id, 'zone_tick_seconds')), 1)), 'world', jsonb_build_object('speed', _cfg(a.event_id, 'move_speed') / 1000.0, 'foot_speed', _cfg(a.event_id, 'foot_speed') / 1000.0, 'loc_radius', _cfg(a.event_id, 'loc_radius') / 1000.0, 'engage_range', _cfg(a.event_id, 'engage_range') / 1000.0, 'glide_range', _cfg(a.event_id, 'glide_range') / 1000.0, 'fire_from_phase', _cfg(a.event_id, 'fire_from_phase'))) || case when a.red_at is not null then jsonb_build_object('red', jsonb_build_object('x', a.red_x, 'y', a.red_y, 'r', a.red_r, 'at', a.red_at)) else '{}'::jsonb end where id = p_arena; end $$; do $$ declare d text; n text; begin d := pg_get_functiondef('_tick_core(uuid, boolean)'::regprocedure); n := d; n := regexp_replace(n, 'c := _zone_circle\(a\.event_id, a\.zone_stage\);(\s*)v_tick := greatest\(2,', 'c := _zone_now(p_arena);\1v_tick := greatest(2,'); n := replace(n, '_cfg(a.event_id, ''zone_tick_damage'')', '_zone_dmg(a.event_id, a.zone_stage)'); n := replace(n, 'a.zone_next_at is null and a.zone_stage < 5', 'a.zone_next_at is null and a.zone_stage < 5 and coalesce(a.zone_shrink_until, now()) <= now()'); if n = d or position('_zone_now(p_arena)' in n) = 0 or position('_zone_dmg(' in n) = 0 or position('zone_shrink_until' in n) = 0 then raise exception 'v6: could not patch the game clock (_tick_core)'; end if; execute n; end $$; create or replace function _team_speed(t teams) returns float8 language sql stable as $$ select (case when t.vehicle = 'in' or _cfg(t.event_id, 'br_mode') = 0 then _cfg(t.event_id, 'move_speed') else _cfg(t.event_id, 'foot_speed') end) / 1000.0 $$; create or replace function _buggy_bay(p_number int, p_x float8, p_y float8) returns float8[] language plpgsql immutable as $$ declare l record; i int := (greatest(1, p_number) - 1) % 16; begin select * into l from (values ('park_sw', 0.12, 0.83, 0.42, 0.95), ('park_se', 0.58, 0.83, 0.88, 0.95), ('park_dc', 0.70, 0.37, 0.765, 0.43)) v(id, x0, y0, x1, y1) order by ((x0 + x1) / 2 - p_x) ^ 2 + ((y0 + y1) / 2 - p_y) ^ 2 limit 1; return array[l.x0 + (l.x1 - l.x0) * (0.08 + 0.84 * (i % 8) / 7.0), l.y0 + (l.y1 - l.y0) * (case when i < 8 then 0.3 else 0.7 end)]; end $$; create or replace function _in_building(p_x float8, p_y float8) returns text language sql stable as $$ select id from buildings where p_x between x0 and x1 and p_y between y0 and y1 limit 1 $$; create or replace function captain_steer(p_token text, p_x double precision, p_y double precision, p_vx double precision default 0, p_vy double precision default 0) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; cur float8[]; dt float8; maxd float8; d float8; nx float8; ny float8; v_loc text; v_others int; v_ping boolean; b buildings; v_spd float8; v_vx float8; v_vy float8; v_vm float8; v_pick jsonb; v_wall text; v_parked boolean := false; v_veh text; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state = 'recovery' then raise exception 'BUSY'; end if; if not t.dropped and _cfg(t.event_id, 'br_mode') = 1 then if t.state = 'traveling' then raise exception 'BUSY'; end if; raise exception 'JUMP_FIRST'; end if; if not t.dropped then t.vehicle := 'in'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; if p_x is null or p_y is null or p_x = 'NaN'::float8 or p_y = 'NaN'::float8 or abs(p_x) = 'Infinity'::float8 or abs(p_y) = 'Infinity'::float8 then raise exception 'BAD_REQUEST'; end if; cur := _team_xy(t); v_veh := t.vehicle; v_spd := _team_speed(t); dt := least(4, greatest(0, extract(epoch from now() - coalesce(case when t.state = 'traveling' then now() else t.pos_at end, now() - interval '1 second')))); if t.state = 'traveling' then dt := 0.25; end if; maxd := v_spd * dt * 1.25 + 0.003; nx := greatest(0.02, least(0.98, p_x)); ny := greatest(0.02, least(0.98, p_y)); d := sqrt((nx - cur[1]) ^ 2 + (ny - cur[2]) ^ 2); if d > maxd then nx := cur[1] + (nx - cur[1]) * maxd / d; ny := cur[2] + (ny - cur[2]) * maxd / d; end if; if t.level > 0 then select * into b from buildings where id = t.bldg; if b.id is not null then nx := greatest(b.x0 + 0.004, least(b.x1 - 0.004, nx)); ny := greatest(b.y0 + 0.004, least(b.y1 - 0.004, ny)); end if; else select bb.id into v_wall from buildings bb where nx between bb.x0 and bb.x1 and ny between bb.y0 and bb.y1 and _sealed(t.arena_id, bb.id, 0) and not (cur[1] between bb.x0 and bb.x1 and cur[2] between bb.y0 and bb.y1) limit 1; if v_wall is not null then nx := cur[1]; ny := cur[2]; end if; if v_wall is null and v_veh = 'in' and _in_building(nx, ny) is not null and _in_building(cur[1], cur[2]) is null then nx := cur[1]; ny := cur[2]; v_veh := 'parked'; v_parked := true; end if; end if; v_vx := coalesce(p_vx, 0); v_vy := coalesce(p_vy, 0); if v_vx = 'NaN'::float8 or v_vy = 'NaN'::float8 or abs(v_vx) = 'Infinity'::float8 or abs(v_vy) = 'Infinity'::float8 then v_vx := 0; v_vy := 0; end if; v_vm := sqrt(v_vx ^ 2 + v_vy ^ 2); if v_vm > v_spd * 1.1 then v_vx := v_vx * v_spd * 1.1 / v_vm; v_vy := v_vy * v_spd * 1.1 / v_vm; end if; if v_wall is not null or v_parked then v_vx := 0; v_vy := 0; end if; v_loc := _loc_at3(t.arena_id, t.event_id, nx, ny, t.level, t.bldg); if v_loc is distinct from t.location_id then update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; end if; v_ping := v_parked or v_loc is distinct from t.location_id or t.last_steer_ping is null or t.last_steer_ping < now() - interval '2 seconds'; update teams set pos_x = nx, pos_y = ny, pos_at = now(), vel_x = v_vx, vel_y = v_vy, dropped = true, location_id = v_loc, state = 'idle', travel_to = null, travel_from = null, travel_started_at = null, travel_arrive_at = null, visit_missions = case when v_loc is distinct from t.location_id then 0 else visit_missions end, last_steer_ping = case when v_ping then now() else last_steer_ping end, vehicle = v_veh, buggy_x = case when v_veh = 'in' or v_parked then nx else buggy_x end, buggy_y = case when v_veh = 'in' or v_parked then ny else buggy_y end where id = t.id; if v_loc is not null and v_loc is distinct from t.location_id then if t.jammed_until is null or t.jammed_until < now() then perform _feed(t.arena_id, 'squad.arrived', jsonb_build_object('team', t.number, 'location', v_loc)); end if; select count(*) into v_others from teams x where x.arena_id = t.arena_id and x.ready and x.id <> t.id and x.location_id = v_loc; if v_others > 0 then perform _feed(t.arena_id, 'encounter.detected', jsonb_build_object('location', v_loc, 'squads', v_others + 1)); perform _ping_arena(t.arena_id, 'encounter'); end if; end if; v_pick := _take_pickups(t.id, nx, ny); if v_ping or v_pick is not null then perform _ping_team(t.id, 'move'); end if; return jsonb_build_object('x', nx, 'y', ny, 'location', v_loc, 'level', t.level, 'clamped', abs(nx - p_x) > 0.0005 or abs(ny - p_y) > 0.0005, 'wall', v_wall, 'picked', v_pick, 'vehicle', v_veh, 'parked', v_parked); end $$; create or replace function captain_vehicle(p_token text, p_in boolean) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; cur float8[]; v_first boolean; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state in ('recovery', 'traveling') or not t.dropped then raise exception 'BUSY'; end if; cur := _team_xy(t); if coalesce(p_in, true) then if t.vehicle = 'in' then return jsonb_build_object('vehicle', 'in'); end if; if t.level > 0 then raise exception 'TAKE_THE_STAIRS'; end if; if t.buggy_x is null then update teams set buggy_x = (_buggy_bay(t.number, cur[1], cur[2]))[1], buggy_y = (_buggy_bay(t.number, cur[1], cur[2]))[2] where id = t.id returning * into t; end if; if (t.buggy_x - cur[1]) ^ 2 + (t.buggy_y - cur[2]) ^ 2 > 0.009 ^ 2 then raise exception 'BUGGY_TOO_FAR'; end if; v_first := t.vehicle = 'none'; update teams set vehicle = 'in', pos_x = t.buggy_x, pos_y = t.buggy_y, pos_at = now(), vel_x = 0, vel_y = 0 where id = t.id; if v_first then perform _feed(t.arena_id, 'squad.buggy', jsonb_build_object('team', t.number)); end if; else if t.vehicle <> 'in' then return jsonb_build_object('vehicle', t.vehicle); end if; update teams set vehicle = 'parked', buggy_x = cur[1], buggy_y = cur[2], vel_x = 0, vel_y = 0, pos_at = now() where id = t.id; end if; perform _ping_team(t.id, 'vehicle'); return jsonb_build_object('vehicle', case when coalesce(p_in, true) then 'in' else 'parked' end); end $$; do $$ declare d text; n text; begin d := pg_get_functiondef('captain_stairs(text, integer)'::regprocedure); n := replace(d, 'if p_dir is null or p_dir not in (-1, 1) then raise exception ''BAD_REQUEST''; end if;', 'if p_dir is null or p_dir not in (-1, 1) then raise exception ''BAD_REQUEST''; end if;
  if not t.dropped then raise exception ''JUMP_FIRST''; end if;
  if t.vehicle = ''in'' then
    cur := _team_xy(t);
    update teams set vehicle = ''parked'', buggy_x = cur[1], buggy_y = cur[2] where id = t.id;
  end if;'); if n = d then raise exception 'v6: could not patch captain_stairs'; end if; execute n; end $$;
